using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoffeeRoadsideProbe{static CoffeeRoadsideProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoffeeRoadsideProbe.request"))return;File.Delete("CoffeeRoadsideProbe.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var log=new List<string>();foreach(var f in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(g=>new[]{"billboard (20)","billboard (46)","Circus_Circus_0 (1)","Circus_Circus_0 (2)"}.Contains(g.name))){var d=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var p=(Vector3[])d.GetType().GetField("p").GetValue(d);var uv=(Vector2[][])d.GetType().GetField("uv").GetValue(d);var ids=(int[])d.GetType().GetField("ids").GetValue(d);log.Add(f.name+" bounds="+f.GetComponent<Renderer>().bounds+" position="+f.transform.position+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh));File.WriteAllLines("FinalEnvironmentRoadReview/"+f.name+"-current.csv",new[]{"i,x,y,z,u,v"}.Concat(Enumerable.Range(0,p.Length).Select(i=>{var w=f.transform.TransformPoint(p[i]);return i+","+w.x+","+w.y+","+w.z+","+uv[0][i].x+","+uv[0][i].y;})));File.WriteAllText("FinalEnvironmentRoadReview/"+f.name+"-current-ids.txt",string.Join(",",ids));if(f.name.StartsWith("billboard"))for(int k=0;k<ids.Length;k+=3){var a=f.transform.TransformPoint(p[ids[k]]);var b=f.transform.TransformPoint(p[ids[k+1]]);var c=f.transform.TransformPoint(p[ids[k+2]]);var n=Vector3.Cross(b-a,c-a);if(n.magnitude>5)log.Add(" area="+n.magnitude/2+" normal="+n.normalized+" a="+a+" b="+b+" c="+c);}}File.WriteAllLines("FinalEnvironmentRoadReview/CoffeeRoadsideProbe.txt",log);}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CoffeeRoadsideProbe.txt",e.ToString());}}}
